from lib import *
S = SS('f173')
R = J('f173'); th = R['threads']; lz = R['lazy']; hk = R['harakiri']; bn = R['bench']; kl = list(lz)
steps = [
    step("入口:uwsgi --http 127.0.0.1:端口 --master --module app --callable app 启动,GET / 返回 200 与 {pid, token}。不写 --callable 时,uWSGI 默认去找名叫 application 的变量,而这个应用里叫 app,请求得到 500 Internal Server Error——服务起来了但每个请求都失败(进程没有退出,不像 gunicorn 那样启动时就报错),部署后一定要请求一次验证。", t=tl(S(1)), done=lidx(S(1), '--callable app'), mark=lidx(S(1), '不写 --callable'), kv=KV([['--callable', '默认找 application 变量'], ['写错', '服务起来了,请求 500']], ['写错'])),
    step("线程:我原以为 uWSGI 默认不启用线程支持,视图里自己 new 的 threading.Thread 不会跑,需要 --enable-threads(uWSGI 文档这么写)。实测:这个版本下不加参数时,后台线程也跑了(1 秒后 FLAG = {thread_ran: true}),加 --enable-threads 同样为 true——两种都正常。这个行为是否随版本变化、与 Python 版本有没有关系,我没有查,所以不要拿它当作可以省掉这个参数的依据。", t=tl(S(2)), done=lidx(S(2), '默认', '--enable-threads'), kv=KV([['不加 --enable-threads', '线程仍然运行(本版本观察)'], ['文档的建议', '需要线程时显式加上']], ['不加 --enable-threads'])),
    step(f"--lazy-apps:默认 uWSGI 在 master 里先加载应用再 fork 出 worker,所以导入时算的随机值(TOKEN)在 3 个 worker 里是同一个({lz[kl[0]][0]} 个 worker、{lz[kl[0]][1]} 个值);加 --lazy-apps 让每个 worker 各自加载应用,TOKEN 各不相同({lz[kl[1]][0]} 个 worker、{lz[kl[1]][1]} 个值)。和 gunicorn 的 --preload 是同一回事(第 145 篇),只是 uWSGI 默认就是预加载,gunicorn 默认相反。数据库连接、线程这类 fork 不安全的资源要用 --lazy-apps 或在 worker 启动后再创建。(第一次我用顺序请求,只打到一个 worker,看不出差别,改成 8 个并发客户端才看到全部 worker。)", t=tl(S(3)), done=lidx(S(3), '默认(master', '--lazy-apps'), kv=KV([['默认', '先加载再 fork,共享导入时的值'], ['--lazy-apps', '每个 worker 各自加载']], ['--lazy-apps'])),
    step(f"--harakiri 2(单个请求超过 2 秒就杀掉 worker):5 秒的慢请求得到 {hk[0]}(连接被直接断开,没有 HTTP 响应),大约在 {hk[1]:.0f} ms 时;之后的新请求得到 {hk[2]},worker 被重新拉起。和 gunicorn 的 --timeout 类似,但客户端看到的是断开而不是 500 页面。", t=tl(S(4)), done=lidx(S(4), '慢请求'), kv=KV([['--harakiri', '超时杀 worker,客户端连接被断开']], ['--harakiri'])),
    step(f"吞吐(ApacheBench,32 并发 4000 个请求,同机,各测一次):uwsgi --http 4 进程 {bn['uwsgi']:.0f} 请求/秒,gunicorn sync 4 个 worker {bn['gunicorn']:.0f} 请求/秒。差距可能与 uwsgi --http 多一个 HTTP 路由进程有关(生产里通常用 --socket 加 nginx 的 uwsgi_pass,不走这个路由进程),我没有验证;这只说明「--http 直接对外」这种用法的相对表现,不是两个服务器的完整比较。", b=bars([['uwsgi --http ×4', bn['uwsgi'], f"{bn['uwsgi']:.0f}"], ['gunicorn sync ×4', bn['gunicorn'], f"{bn['gunicorn']:.0f}"]], bn['gunicorn'], mark=[0], done=[1]), t=tl(S(5)), done=lidx(S(5), 'gunicorn'), mark=lidx(S(5), 'uwsgi --http'), kv=KV([['uwsgi --http', f"{bn['uwsgi']:.0f} 请求/秒"], ['gunicorn sync', f"{bn['gunicorn']:.0f} 请求/秒"]], ['uwsgi --http'])),
]
A = mkartf('f173', 173, 'Flask,uWSGI,部署,lazy-apps,harakiri,真实验证,动画演示',
    f'实测 uWSGI 部署 Flask:不写 --callable 时服务起得来但请求 500、线程在这个版本里不加 --enable-threads 也能跑(与文档的说法不同)、默认先加载再 fork 所以 TOKEN 共享而 --lazy-apps 各 worker 不同、--harakiri 2 秒杀掉慢请求并断开连接、--http 直连下 {bn["uwsgi"]:.0f} 对 gunicorn {bn["gunicorn"]:.0f} 请求/秒。',
    'uWSGI 怎么部署 Flask?默认参数有哪些坑?线程、预加载、超时各是什么行为?这篇用真实的 uwsgi 把每个参数的效果验证出来,包括一个和文档不一致的结果。',
    [('--callable', '不写时 uWSGI 找 application 变量,找不到就让每个请求 500'), ('--lazy-apps', '让每个 worker 各自加载应用,避免 fork 共享导入时的资源'), ('线程', '这个版本不加 --enable-threads 线程也运行,与文档说法不同')],
    [('入口与 --callable', '<p>上一篇:<a href="flask-gunicorn-start.html">Gunicorn 启动 Flask</a>;下一篇:<a href="flask-nginx-reverse-proxy.html">Nginx 反向代理</a>。</p>'), ('线程支持', None), ('预加载与 --lazy-apps', None), ('--harakiri', None), ('吞吐', '<p>uwsgi 是装在自己虚拟环境里的版本;压测工具是 ApacheBench,与服务同机运行,每个数字只测一次。</p>')],
    steps, [ENV_F + '。uWSGI(虚拟环境里安装的版本)、gunicorn', '没有验证:--socket 加 nginx 的 uwsgi_pass 的生产用法与吞吐、uwsgi 的 emperor 模式、--processes 与 --threads 的组合、--max-requests、uWSGI 项目进入维护模式后的长期选型建议'], 'uWSGI 与 Flask')
